using System;
using System.Collections.Generic;
using System.Linq;
using System.Text.Json;

namespace BlueMageSetBuilder;

/// <summary>
/// Builds one profile per Masked Carnivale stage from Carnivale.json: the spells Blue
/// Academy's stage guide lists (required first, then recommended), followed by the
/// general Carnivale fill from Profiles.json. Generated by tools/make-carnivale.ps1;
/// see that script for what is and is not taken from the guides.
/// </summary>
public static class CarnivaleSets
{
    private const string ResourceName = "BlueMageSetBuilder.Carnivale.json";

    public const string CreditName = "Blue Academy";
    public const string CreditSite = "mage.blue";
    public const string CreditUrl = "https://mage.blue/masked-carnivale/";

    /// <summary>
    /// Stage profiles, skipping any stage that <paramref name="existing"/> already has a
    /// profile for, so a hand-written stage set in Profiles.json wins.
    /// </summary>
    public static List<Profile> Build(IReadOnlyList<Profile> existing, List<Pick> fill)
    {
        var result = new List<Profile>();
        try
        {
            using var stream = typeof(CarnivaleSets).Assembly.GetManifestResourceStream(ResourceName);
            if (stream is null)
                return result;

            using var doc = JsonDocument.Parse(stream);
            if (!doc.RootElement.TryGetProperty("Stages", out var stages))
                return result;

            foreach (var stage in stages.EnumerateObject())
            {
                if (!int.TryParse(stage.Name, out var number) || existing.Any(p => p.Stage == number))
                    continue;

                var url = stage.Value.TryGetProperty("Url", out var u) ? u.GetString() ?? string.Empty : string.Empty;
                var picks = ReadPicks(stage.Value);

                result.Add(new Profile
                {
                    Id = $"stage{number}",
                    Name = $"Stage {number}",
                    Stage = number,
                    SourceUrl = url,
                    Description = picks.Count > 0
                        ? $"The spells {CreditName}'s guide for this stage calls for come first, then a general Carnivale set fills the remaining slots."
                        : $"{CreditName}'s guide lists no particular spells for this stage, so this is the general Carnivale set.",
                    Picks = picks,
                    Fill = fill,
                });
            }
        }
        catch (Exception ex)
        {
            Service.Log.Warning(ex, "Could not read Carnivale.json; stage sets will be missing");
        }

        return result;
    }

    private static List<Pick> ReadPicks(JsonElement stage)
    {
        var picks = new List<Pick>();
        if (!stage.TryGetProperty("Picks", out var list))
            return picks;

        // PowerShell writes a one-item list as a bare object, so accept both.
        var items = list.ValueKind == JsonValueKind.Array ? list.EnumerateArray().ToList() : new List<JsonElement> { list };
        foreach (var item in items.Where(i => i.ValueKind == JsonValueKind.Object))
        {
            var any = new List<uint>();
            if (item.TryGetProperty("Any", out var a))
            {
                var spells = a.ValueKind == JsonValueKind.Array ? a.EnumerateArray().ToList() : new List<JsonElement> { a };
                any.AddRange(spells.Where(s => s.ValueKind == JsonValueKind.Number).Select(s => s.GetUInt32()));
            }

            if (any.Count == 0)
                continue;

            var required = item.TryGetProperty("Kind", out var k) && k.GetString() == "Required";
            var example = item.TryGetProperty("Example", out var e) && e.ValueKind == JsonValueKind.True;

            picks.Add(new Pick { Spells = any, Why = Why(required, example, any.Count > 1), Required = required });
        }

        return picks;
    }

    // Written here, not copied from the guide: the guide only supplies which spells.
    private static string Why(bool required, bool example, bool alternatives)
    {
        var what = alternatives ? "Any of these spells" : example ? "A spell like this" : "This spell";
        return required
            ? $"{what} is needed for this stage, per {CreditName}."
            : $"{what} is recommended for this stage by {CreditName}.";
    }
}
